"""Tokenizer for the microvm language."""

from __future__ import annotations

import dataclasses
import re

from .errors import LexError

KEYWORDS: frozenset[str] = frozenset(
    {"let", "print", "if", "else", "while", "true", "false", "and", "or", "not"}
)
_TWO_CHAR_OPS = ("==", "!=", "<=", ">=")
_ONE_CHAR_OPS = frozenset("+-*/%(){};=<>")
_ESCAPES = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}
_NUMBER = re.compile(r"[0-9]+(?:\.[0-9]+(?:[eE][+-]?[0-9]+)?)?")
_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_DIGITS = frozenset("0123456789")
_IDENT_CHARS = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_")


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    offset: int


def _lex_number(src: str, pos: int) -> Token:
    match = _NUMBER.match(src, pos)
    assert match is not None
    end = match.end()
    if end < len(src) and (src[end] == "." or src[end] in _IDENT_CHARS):
        # "1.", "1.5.", "1.5e", "12abc": reported at the start of the literal.
        raise LexError("malformed number literal", pos)
    text = match.group(0)
    if "." in text:
        return Token("FLOAT", text, float(text), pos)
    return Token("INT", text, int(text), pos)


def _lex_string(src: str, pos: int) -> tuple[Token, int]:
    chars: list[str] = []
    i = pos + 1
    while i < len(src):
        ch = src[i]
        if ch == '"':
            value = "".join(chars)
            return Token("STRING", value, value, pos), i + 1
        if ch == "\n":
            raise LexError("newline inside string literal", i)
        if ch == "\\":
            if i + 1 >= len(src):
                break
            escaped = _ESCAPES.get(src[i + 1])
            if escaped is None:
                raise LexError("invalid escape sequence", i)
            chars.append(escaped)
            i += 2
            continue
        chars.append(ch)
        i += 1
    raise LexError("unterminated string literal", pos)


def _lex_operator(src: str, pos: int) -> Token:
    two = src[pos:pos + 2]
    if two in _TWO_CHAR_OPS:
        return Token("OP", two, two, pos)
    if src[pos] in _ONE_CHAR_OPS:
        return Token("OP", src[pos], src[pos], pos)
    raise LexError(f"unexpected character {src[pos]!r}", pos)


def tokenize(src: str) -> list[Token]:
    """Split ``src`` into tokens; no end-of-input token is emitted."""
    if not isinstance(src, str):
        raise TypeError("source must be a str")
    tokens: list[Token] = []
    pos = 0
    length = len(src)
    while pos < length:
        ch = src[pos]
        if ch.isspace():
            pos += 1
        elif src.startswith("//", pos):
            newline = src.find("\n", pos)
            pos = length if newline < 0 else newline
        elif ch in _DIGITS:
            token = _lex_number(src, pos)
            tokens.append(token)
            pos += len(token.text)
        elif ch == '"':
            token, pos = _lex_string(src, pos)
            tokens.append(token)
        elif ch in _IDENT_CHARS:
            match = _IDENT.match(src, pos)
            assert match is not None
            word = match.group(0)
            kind = "KEYWORD" if word in KEYWORDS else "IDENT"
            tokens.append(Token(kind, word, word, pos))
            pos = match.end()
        else:
            token = _lex_operator(src, pos)
            tokens.append(token)
            pos += len(token.text)
    return tokens

"""Recursive-descent parser producing a small dataclass AST."""

from __future__ import annotations

import contextlib
import dataclasses
import sys
from typing import Iterator, Optional

from .errors import ParseError
from .lexer import Token, tokenize

_COMPARISONS = frozenset({"==", "!=", "<", "<=", ">", ">="})
_RECURSION_LIMIT = 20_000


@dataclasses.dataclass(frozen=True)
class Literal:
    value: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Name:
    name: str
    offset: int


@dataclasses.dataclass(frozen=True)
class Unary:
    op: str
    operand: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Binary:
    op: str
    left: object
    right: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Let:
    name: str
    value: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Assign:
    name: str
    value: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Print:
    value: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Block:
    body: tuple
    offset: int


@dataclasses.dataclass(frozen=True)
class If:
    cond: object
    then: Block
    orelse: object  # None, a Block, or a nested If
    offset: int


@dataclasses.dataclass(frozen=True)
class While:
    cond: object
    body: Block
    offset: int


@dataclasses.dataclass(frozen=True)
class Module:
    body: tuple


@contextlib.contextmanager
def deep_recursion() -> Iterator[None]:
    """Temporarily allow deeper recursion for deeply nested programs."""
    old = sys.getrecursionlimit()
    sys.setrecursionlimit(max(old, _RECURSION_LIMIT))
    try:
        yield
    finally:
        sys.setrecursionlimit(old)


class _Parser:
    def __init__(self, src: str, tokens: list[Token]) -> None:
        self.src = src
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Optional[Token]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def at(self, kind: str, text: Optional[str] = None) -> bool:
        tok = self.peek()
        return tok is not None and tok.kind == kind and (text is None or tok.text == text)

    def offset(self) -> int:
        tok = self.peek()
        return tok.offset if tok is not None else len(self.src)

    def error(self, message: str) -> ParseError:
        tok = self.peek()
        found = "end of input" if tok is None else repr(tok.text)
        return ParseError(f"{message}, found {found}", self.offset())

    def advance(self) -> Token:
        tok = self.peek()
        if tok is None:
            raise self.error("unexpected end of input")
        self.pos += 1
        return tok

    def expect(self, kind: str, text: Optional[str] = None) -> Token:
        if not self.at(kind, text):
            raise self.error(f"expected {text if text is not None else kind}")
        return self.advance()

    def program(self) -> Module:
        body = []
        while self.peek() is not None:
            body.append(self.statement())
        return Module(tuple(body))

    def statement(self) -> object:
        tok = self.peek()
        if tok is None:
            raise self.error("expected statement")
        if tok.kind == "KEYWORD" and tok.text == "let":
            self.advance()
            name = self.expect("IDENT")
            self.expect("OP", "=")
            value = self.expression()
            self.expect("OP", ";")
            return Let(name.text, value, tok.offset)
        if tok.kind == "KEYWORD" and tok.text == "print":
            self.advance()
            value = self.expression()
            self.expect("OP", ";")
            return Print(value, tok.offset)
        if tok.kind == "KEYWORD" and tok.text == "if":
            return self.if_statement()
        if tok.kind == "KEYWORD" and tok.text == "while":
            self.advance()
            cond = self.condition()
            return While(cond, self.block(), tok.offset)
        if tok.kind == "OP" and tok.text == "{":
            return self.block()
        if tok.kind == "IDENT":
            self.advance()
            self.expect("OP", "=")
            value = self.expression()
            self.expect("OP", ";")
            return Assign(tok.text, value, tok.offset)
        raise self.error("expected statement")

    def condition(self) -> object:
        self.expect("OP", "(")
        cond = self.expression()
        self.expect("OP", ")")
        return cond

    def if_statement(self) -> If:
        tok = self.expect("KEYWORD", "if")
        cond = self.condition()
        then = self.block()
        orelse: object = None
        if self.at("KEYWORD", "else"):
            self.advance()
            orelse = self.if_statement() if self.at("KEYWORD", "if") else self.block()
        return If(cond, then, orelse, tok.offset)

    def block(self) -> Block:
        start = self.expect("OP", "{")
        body = []
        while not self.at("OP", "}"):
            if self.peek() is None:
                raise self.error("expected '}'")
            body.append(self.statement())
        self.advance()
        return Block(tuple(body), start.offset)

    def expression(self) -> object:
        return self.logical("or", self.and_expr)

    def and_expr(self) -> object:
        return self.logical("and", self.not_expr)

    def logical(self, keyword: str, operand: "callable") -> object:
        left = operand()
        while self.at("KEYWORD", keyword):
            tok = self.advance()
            left = Binary(keyword, left, operand(), tok.offset)
        return left

    def not_expr(self) -> object:
        if self.at("KEYWORD", "not"):
            tok = self.advance()
            return Unary("not", self.not_expr(), tok.offset)
        return self.comparison()

    def comparison(self) -> object:
        left = self.additive()
        tok = self.peek()
        if tok is not None and tok.kind == "OP" and tok.text in _COMPARISONS:
            self.advance()
            left = Binary(tok.text, left, self.additive(), tok.offset)
            nxt = self.peek()
            if nxt is not None and nxt.kind == "OP" and nxt.text in _COMPARISONS:
                raise self.error("comparison operators are not associative")
        return left

    def binary_chain(self, ops: frozenset, operand: "callable") -> object:
        left = operand()
        while True:
            tok = self.peek()
            if tok is None or tok.kind != "OP" or tok.text not in ops:
                return left
            self.advance()
            left = Binary(tok.text, left, operand(), tok.offset)

    def additive(self) -> object:
        return self.binary_chain(frozenset({"+", "-"}), self.multiplicative)

    def multiplicative(self) -> object:
        return self.binary_chain(frozenset({"*", "/", "%"}), self.unary)

    def unary(self) -> object:
        if self.at("OP", "-"):
            tok = self.advance()
            return Unary("-", self.unary(), tok.offset)
        return self.primary()

    def primary(self) -> object:
        tok = self.peek()
        if tok is None:
            raise self.error("expected expression")
        if tok.kind in ("INT", "FLOAT", "STRING"):
            self.advance()
            return Literal(tok.value, tok.offset)
        if tok.kind == "KEYWORD" and tok.text in ("true", "false"):
            self.advance()
            return Literal(tok.text == "true", tok.offset)
        if tok.kind == "IDENT":
            self.advance()
            return Name(tok.text, tok.offset)
        if tok.kind == "OP" and tok.text == "(":
            self.advance()
            inner = self.expression()
            self.expect("OP", ")")
            return inner
        raise self.error("expected expression")


def parse(src: str) -> object:
    """Parse ``src`` into an AST (a ``Module``); raises ``ParseError``/``LexError``."""
    tokens = tokenize(src)
    parser = _Parser(src, tokens)
    try:
        with deep_recursion():
            return parser.program()
    except RecursionError:
        raise ParseError("program is nested too deeply", parser.offset()) from None

"""Stack virtual machine and the runtime semantics of every operator."""

from __future__ import annotations

from typing import Callable

from .compiler import Program
from .errors import StepLimitError, VMRuntimeError

_UNSET = object()


def type_name(value: object) -> str:
    """Return the language-level type name of ``value``."""
    kind = type(value)
    if kind is bool:
        return "BOOL"
    if kind is int:
        return "INT"
    if kind is float:
        return "FLOAT"
    if kind is str:
        return "STRING"
    return kind.__name__


def _is_num(value: object) -> bool:
    # bool is deliberately excluded: it is not a number in this language.
    return type(value) is int or type(value) is float


def render(value: object) -> str:
    """Render a value the way ``print`` shows it."""
    if type(value) is bool:
        return "true" if value else "false"
    return str(value)


def _type_error(op: str, *values: object) -> VMRuntimeError:
    types = ", ".join(type_name(v) for v in values)
    return VMRuntimeError(f"unsupported operand type(s) for {op}: {types}")


def _numeric(op: str, a: object, b: object, fn: Callable[[object, object], object]) -> object:
    if not (_is_num(a) and _is_num(b)):
        raise _type_error(op, a, b)
    return fn(a, b)


def _add(a: object, b: object) -> object:
    if type(a) is str and type(b) is str:
        return a + b
    return _numeric("ADD", a, b, lambda x, y: x + y)


def _div(a: object, b: object) -> object:
    if not (_is_num(a) and _is_num(b)):
        raise _type_error("DIV", a, b)
    if b == 0:
        raise VMRuntimeError("division by zero")
    return float(a / b)


def _mod(a: object, b: object) -> object:
    if type(a) is not int or type(b) is not int:
        raise _type_error("MOD", a, b)
    if b == 0:
        raise VMRuntimeError("modulo by zero")
    return a % b


def _equal(a: object, b: object) -> bool:
    if (type(a) is bool) != (type(b) is bool):
        return False
    return bool(a == b)


def _ordered(op: str, fn: Callable[[object, object], bool]) -> Callable[[object, object], bool]:
    def compare(a: object, b: object) -> bool:
        if (_is_num(a) and _is_num(b)) or (type(a) is str and type(b) is str):
            return fn(a, b)
        raise _type_error(op, a, b)
    return compare


_BINARY: dict[str, Callable[[object, object], object]] = {
    "ADD": _add,
    "SUB": lambda a, b: _numeric("SUB", a, b, lambda x, y: x - y),
    "MUL": lambda a, b: _numeric("MUL", a, b, lambda x, y: x * y),
    "DIV": _div,
    "MOD": _mod,
    "EQ": _equal,
    "NE": lambda a, b: not _equal(a, b),
    "LT": _ordered("LT", lambda a, b: a < b),
    "LE": _ordered("LE", lambda a, b: a <= b),
    "GT": _ordered("GT", lambda a, b: a > b),
    "GE": _ordered("GE", lambda a, b: a >= b),
}


def binary_op(op: str, a: object, b: object) -> object:
    """Apply binary opcode ``op``; every failure is a ``VMRuntimeError``."""
    try:
        return _BINARY[op](a, b)
    except OverflowError as exc:
        raise VMRuntimeError(f"numeric overflow in {op}: {exc}") from None


def unary_op(op: str, a: object) -> object:
    """Apply unary opcode ``op`` (``NEG`` or ``NOT``)."""
    if op == "NEG":
        if not _is_num(a):
            raise _type_error("NEG", a)
        return -a
    if op == "NOT":
        if type(a) is not bool:
            raise _type_error("NOT", a)
        return not a
    raise VMRuntimeError(f"unknown unary opcode {op}")


class _Machine:
    def __init__(self, program: Program) -> None:
        self.program = program
        self.code = list(program.instructions)
        self.slots: list[object] = [_UNSET] * len(program.names)
        self.stack: list[object] = []
        self.output: list[str] = []

    def pop(self) -> object:
        if not self.stack:
            raise VMRuntimeError("stack underflow")
        return self.stack.pop()

    def index(self, arg: object, size: int, what: str) -> int:
        if type(arg) is not int or not 0 <= arg < size:
            raise VMRuntimeError(f"invalid {what} index {arg!r}")
        return arg

    def load(self, arg: object) -> None:
        slot = self.index(arg, len(self.slots), "variable")
        value = self.slots[slot]
        if value is _UNSET:
            raise VMRuntimeError(
                f"variable '{self.program.names[slot]}' read before assignment"
            )
        self.stack.append(value)

    def jump_if_false(self, arg: object, ip: int) -> int:
        cond = self.pop()
        if type(cond) is not bool:
            raise VMRuntimeError(f"condition must be BOOL, got {type_name(cond)}")
        return ip if cond else self.index(arg, len(self.code) + 1, "jump")

    def step(self, op: str, arg: object, ip: int) -> int:
        """Execute one instruction; return the next instruction pointer."""
        if op == "CONST":
            self.stack.append(self.program.constants[
                self.index(arg, len(self.program.constants), "constant")])
        elif op == "LOAD":
            self.load(arg)
        elif op == "STORE":
            self.slots[self.index(arg, len(self.slots), "variable")] = self.pop()
        elif op == "JUMP":
            return self.index(arg, len(self.code) + 1, "jump")
        elif op == "JUMP_IF_FALSE":
            return self.jump_if_false(arg, ip)
        elif op == "PRINT":
            self.output.append(render(self.pop()))
        elif op == "POP":
            self.pop()
        elif op in ("NEG", "NOT"):
            self.stack.append(unary_op(op, self.pop()))
        elif op in _BINARY:
            right = self.pop()
            left = self.pop()
            self.stack.append(binary_op(op, left, right))
        else:
            raise VMRuntimeError(f"unknown opcode {op!r}")
        return ip


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    """Run ``program`` and return its printed lines."""
    if type(step_limit) is not int or step_limit <= 0:
        raise ValueError("step_limit must be a positive int")
    machine = _Machine(program)
    code = machine.code
    ip = 0
    steps = 0
    while True:
        if not 0 <= ip < len(code):
            raise VMRuntimeError(f"instruction pointer {ip} out of range (missing HALT?)")
        steps += 1
        if steps > step_limit:
            raise StepLimitError(f"step limit of {step_limit} exceeded")
        instr = code[ip]
        if instr.op == "HALT":
            return machine.output
        ip = machine.step(instr.op, instr.arg, ip + 1)

"""Behaviour-preserving constant folding over the AST."""

from __future__ import annotations

import dataclasses

from .errors import VMRuntimeError
from .opcodes import BINARY_OPCODES, UNARY_OPCODES
from .parser import Assign, Binary, Block, If, Let, Literal, Module, Print, Unary, While
from .vm import binary_op, unary_op

_I64_MIN = -(2 ** 63)
_I64_MAX = 2 ** 63 - 1


def _is_bool_literal(node: object) -> bool:
    return isinstance(node, Literal) and type(node.value) is bool


def _foldable_result(value: object) -> bool:
    # An INT that does not fit in i64 would make dumps() fail where the unfolded
    # program serializes fine, so such results are left unfolded.
    return type(value) is not int or _I64_MIN <= value <= _I64_MAX


def _fold_logical(node: Binary, left: object, right: object) -> object:
    short_value = node.op == "or"  # the left value that decides the result alone
    if _is_bool_literal(left) and left.value is short_value:
        return Literal(short_value, node.offset)
    if _is_bool_literal(left) and _is_bool_literal(right):
        result = (left.value and right.value) if node.op == "and" else (left.value or right.value)
        return Literal(result, node.offset)
    # "true and X" / "false or X" keep X's run-time BOOL check, so they stay.
    return Binary(node.op, left, right, node.offset)


def _fold_binary(node: Binary) -> object:
    left = fold_constants(node.left)
    right = fold_constants(node.right)
    if node.op in ("and", "or"):
        return _fold_logical(node, left, right)
    if isinstance(left, Literal) and isinstance(right, Literal):
        try:
            value = binary_op(BINARY_OPCODES[node.op], left.value, right.value)
        except VMRuntimeError:
            pass  # would fail at run time: keep it so it still fails there
        else:
            if _foldable_result(value):
                return Literal(value, node.offset)
    return Binary(node.op, left, right, node.offset)


def _fold_unary(node: Unary) -> object:
    operand = fold_constants(node.operand)
    if isinstance(operand, Literal):
        try:
            value = unary_op(UNARY_OPCODES[node.op], operand.value)
        except VMRuntimeError:
            pass
        else:
            if _foldable_result(value):
                return Literal(value, node.offset)
    return Unary(node.op, operand, node.offset)


def fold_constants(node: object) -> object:
    """Return a new AST with every safely foldable constant expression folded."""
    if isinstance(node, Binary):
        return _fold_binary(node)
    if isinstance(node, Unary):
        return _fold_unary(node)
    if isinstance(node, (Module, Block)):
        return dataclasses.replace(node, body=tuple(fold_constants(s) for s in node.body))
    if isinstance(node, (Let, Assign, Print)):
        return dataclasses.replace(node, value=fold_constants(node.value))
    if isinstance(node, If):
        orelse = None if node.orelse is None else fold_constants(node.orelse)
        return If(fold_constants(node.cond), fold_constants(node.then), orelse, node.offset)
    if isinstance(node, While):
        return While(fold_constants(node.cond), fold_constants(node.body), node.offset)
    return node

"""Code generation from the AST to stack-machine bytecode."""

from __future__ import annotations

import dataclasses
import struct
from typing import Iterator, Optional

from .errors import CompileError
from .opcodes import ARG_OPCODES, BINARY_OPCODES, OPCODES, UNARY_OPCODES
from .optimizer import fold_constants
from .parser import (
    Assign, Binary, Block, If, Let, Literal, Module, Name, Print, Unary, While,
    deep_recursion, parse,
)


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str
    arg: Optional[int]

    def __post_init__(self) -> None:
        if self.op not in OPCODES:
            raise ValueError(f"unknown opcode {self.op!r}")
        if (self.arg is None) == (self.op in ARG_OPCODES):
            raise ValueError(f"bad argument {self.arg!r} for opcode {self.op}")


@dataclasses.dataclass
class Program:
    constants: list
    names: list[str]
    instructions: list


def _children(node: object) -> Iterator[object]:
    for field in dataclasses.fields(node):
        value = getattr(node, field.name)
        items = value if isinstance(value, tuple) else (value,)
        for item in items:
            if dataclasses.is_dataclass(item):
                yield item


def _walk(node: object) -> Iterator[object]:
    """Yield every AST node in source (pre-)order, without recursion."""
    stack = [node]
    while stack:
        current = stack.pop()
        yield current
        stack.extend(reversed(list(_children(current))))


def _resolve_names(tree: Module) -> list[str]:
    # Blocks do not create scope and a `let` declares its name for the whole
    # program, so declarations are collected up front (slot order = source order)
    # and a read before the `let` executes is a run-time error, not a compile error.
    names: list[str] = []
    for node in _walk(tree):
        if isinstance(node, Let):
            if node.name in names:
                raise CompileError(f"variable '{node.name}' declared twice")
            names.append(node.name)
    declared = set(names)
    for node in _walk(tree):
        if isinstance(node, (Name, Assign)) and node.name not in declared:
            raise CompileError(f"variable '{node.name}' is not declared")
    return names


def _constant_key(value: object) -> tuple:
    if type(value) is float:
        # Keyed by bit pattern so 0.0 / -0.0 and NaN are kept faithfully.
        return ("FLOAT", struct.pack(">d", value))
    return (type(value).__name__, value)


class _CodeGen:
    def __init__(self, names: list[str]) -> None:
        self.names = names
        self.slots = {name: index for index, name in enumerate(names)}
        self.constants: list = []
        self.const_index: dict[tuple, int] = {}
        self.code: list[Instr] = []

    def emit(self, op: str, arg: Optional[int] = None) -> int:
        self.code.append(Instr(op, arg))
        return len(self.code) - 1

    def patch(self, index: int) -> None:
        """Point the jump at ``index`` to the next instruction to be emitted."""
        self.code[index] = Instr(self.code[index].op, len(self.code))

    def constant(self, value: object) -> None:
        key = _constant_key(value)
        if key not in self.const_index:
            self.const_index[key] = len(self.constants)
            self.constants.append(value)
        self.emit("CONST", self.const_index[key])

    def statement(self, node: object) -> None:
        if isinstance(node, (Let, Assign)):
            self.expression(node.value)
            self.emit("STORE", self.slots[node.name])
        elif isinstance(node, Print):
            self.expression(node.value)
            self.emit("PRINT")
        elif isinstance(node, (Block, Module)):
            for child in node.body:
                self.statement(child)
        elif isinstance(node, If):
            self.if_statement(node)
        elif isinstance(node, While):
            start = len(self.code)
            self.expression(node.cond)
            exit_jump = self.emit("JUMP_IF_FALSE", 0)
            self.statement(node.body)
            self.emit("JUMP", start)
            self.patch(exit_jump)
        else:
            raise CompileError(f"unknown statement node {type(node).__name__}")

    def if_statement(self, node: If) -> None:
        self.expression(node.cond)
        else_jump = self.emit("JUMP_IF_FALSE", 0)
        self.statement(node.then)
        if node.orelse is None:
            self.patch(else_jump)
            return
        end_jump = self.emit("JUMP", 0)
        self.patch(else_jump)
        self.statement(node.orelse)
        self.patch(end_jump)

    def expression(self, node: object) -> None:
        if isinstance(node, Literal):
            self.constant(node.value)
        elif isinstance(node, Name):
            self.emit("LOAD", self.slots[node.name])
        elif isinstance(node, Unary):
            self.expression(node.operand)
            self.emit(UNARY_OPCODES[node.op])
        elif isinstance(node, Binary) and node.op in ("and", "or"):
            self.logical(node)
        elif isinstance(node, Binary):
            self.expression(node.left)
            self.expression(node.right)
            self.emit(BINARY_OPCODES[node.op])
        else:
            raise CompileError(f"unknown expression node {type(node).__name__}")

    def logical(self, node: Binary) -> None:
        # and: L; JIF short; R; NOT; NOT; JUMP end; short: CONST false; end:
        # or:  L; JIF long; CONST true; JUMP end; long: R; NOT; NOT; end:
        # JUMP_IF_FALSE checks that L is BOOL; NOT NOT checks R is BOOL, keeping it.
        self.expression(node.left)
        branch = self.emit("JUMP_IF_FALSE", 0)
        if node.op == "and":
            self.checked_bool(node.right)
            end = self.emit("JUMP", 0)
            self.patch(branch)
            self.constant(False)
        else:
            self.constant(True)
            end = self.emit("JUMP", 0)
            self.patch(branch)
            self.checked_bool(node.right)
        self.patch(end)

    def checked_bool(self, node: object) -> None:
        self.expression(node)
        self.emit("NOT")
        self.emit("NOT")


def compile_source(src: str, *, optimize: bool = False) -> Program:
    """Compile source text into a ``Program``."""
    tree = parse(src)
    names = _resolve_names(tree)
    try:
        with deep_recursion():
            if optimize:
                tree = fold_constants(tree)
            gen = _CodeGen(names)
            gen.statement(tree)
    except RecursionError:
        raise CompileError("program is nested too deeply") from None
    gen.emit("HALT")
    return Program(constants=gen.constants, names=list(names), instructions=gen.code)

